/// <summary>
/// MPJ_28155_SalesFinalisation 3.6.5 Transfer shipment to existing load and 3.6.6 Transfer shipment to new load
/// This is adapted from class <c>WHSShipmentDetailsForm</c>
/// </summary>
class METShipmentDetailsForm
{
    boolean validated = true;
    
}

Method.Source:
    /// <summary>
    /// Performs lookup for load id.
    /// </summary>
    /// <param name="_ctrl">
    /// Form control.
    /// </param>
    protected void loadIdDialogControl_Lookup(FormStringControl _ctrl)
    {
        SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(METShipmentTable), _ctrl);
        Query                   query = new Query();
        QueryBuildDataSource    queryBuildDataSource = query.addDataSource(tableNum(METShipmentTable));        

        //exclude Shipped and Received loads
        //queryBuildDataSource.addRange(fieldNum(WHSLoadTable, LoadStatus)).value(strFmt("..%1", queryValue(WHSLoadStatus::Loaded)));

        queryBuildDataSource.addGroupByField(fieldNum(METShipmentTable, LoadId));
        sysTableLookup.addLookupfield(fieldNum(METShipmentTable, LoadId));
        //sysTableLookup.addLookupfield(fieldNum(METShipmentTable, ShipmentStatus));

        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
    }

    /// <summary>
    /// Validate load id.
    /// </summary>
    /// <param name="_ctrl">
    /// Form control.
    /// </param>
    /// <returns>True if it's a valid Load ID; otherwise, false</returns>
    [SuppressBPWarning('BPUnusedStrFmtArgument', 'BP bug')]
    protected boolean loadIdDialogControl_Validate(FormStringControl _ctrl)
    {
        boolean ret = true;
        METLoadId   loadId = _ctrl.text();

        if (!METShipmentTable::existLoadId(loadId))
        {
            ret = checkfailed(strFmt("@MET:ValidateLoadId", loadId));
        }

        return ret;
    }

    /// <summary>
    /// Transfers shipment to a load when button is clicked.
    /// </summary>
    /// <param name="_shipmentTable">
    /// Shipment to be transferred.
    /// </param>
    /// <returns>true if the dialog could be successfully created; otherwise false.</returns>
    boolean Transfer_clicked(METShipmentTable   _shipmentTable)
    {
        boolean ret = true;
        Dialog dialog = new dialog("@WAX2969");
        dialog.formBuildDesign().dialogSize(DialogSize::Small);
        DialogField loadId = dialog.addField(extendedTypeStr(METLoadId));

        loadId.registerOverrideMethod(identifierStr(lookup), methodStr(METShipmentDetailsForm, loadIdDialogControl_Lookup), this);
        loadId.registerOverrideMethod(identifierStr(validate), methodStr(METShipmentDetailsForm, loadIdDialogControl_Validate), this);

        if (dialog.run())
        {
            _shipmentTable.transferShipment(loadId.value());
        }

        return ret;
    }

    /// <summary>
    /// Creates a dialog with all the load template information needed for transfering a shipment to a new load.
    /// </summary>
    /// <param name = "_metShipmentTable">The current shipment</param>
    /// <returns>true if the dialog could be successfully created; otherwise false.</returns>
    public boolean transferToNewLoad(METShipmentTable _metShipmentTable)
    {
        boolean ret = true;
        NumberSeq   numberSeq;
        METLoadId newLoadId;

        numberSeq = NumberSeq::newGetNum(WHSParameters::numRefMETLoadId());
        newLoadId = numberSeq.num();

        _metShipmentTable.transferShipment(newLoadId);        
       
        return ret;
    }
